SELECT s0."rid_documents_document" AS "$k0", s0."f_document_title" AS "title", s0."member_of_documents_document" AS "kind", j1."f_client_preferred_name" AS "client.preferred_name" FROM "tbl_documents_document" AS s0 LEFT JOIN "tbl_clients_client" AS j1 ON j1."rid_clients_client" = s0."ref_document_client" WHERE s0."f_document_archived_at" IS NULL AND s0."ref_document_owner" = :_scope AND (s0."ref_document_client" = :client) ORDER BY s0."f_document_title" ASC, s0."rid_documents_document" ASC
